arguments.command:
cd /testbed && perl -0777 -pi -e 's/labels = iter\(labels\)
    if colors is not None:
        axes\.set_prop_cycle\(color=colors\)
/labels = iter(labels)

    if colors is not None:
        # Do not modify the Axes property cycler; stackplot is a composite
        # plot that should not have side effects on subsequent plotting calls.
        #
        # In particular, users may pass colors specified as "C0", "C1", ...
        # (cycle references), which are valid color specifications for artists
        # but cannot be stored in a property cycler.
        if isinstance(colors, str):
            colors = [colors]
        colors = list(colors)
        if len(colors) == 0:
            raise ValueError("colors must contain at least one color")
        color_cycle = itertools.cycle(colors)

        def get_color():
            return next(color_cycle)
    else:
        get_color = axes._get_lines.get_next_color
/sm' lib/matplotlib/stackplot.py

